\vdots
2^{n-2}\left[a_n - \frac{1}{2}a_{n-1} = \frac{2}{n^2} - \frac{1}{(n-1)^2}\right]
2^{n-1}\left[a_{n+1} - \frac{1}{2}a_n = \frac{2}{(n+1)^2} - \frac{1}{n^2}\right]
Adding
